from fractions import Fraction
from math import gcd

def rational_at(k):
    """The k-th positive rational (k = 1, 2, ...) in the walk."""
    count, s = 0, 2
    while True:
        for p in range(1, s):
            if gcd(p, s - p) == 1:
                count += 1
                if count == k:
                    return Fraction(p, s - p)
        s += 1

def index_of(p, q):
    """The position of p/q in the walk (p, q >= 1)."""
    g = gcd(p, q)
    p, q = p // g, q // g
    k = 0
    for s in range(2, p + q):
        k += sum(1 for a in range(1, s) if gcd(a, s - a) == 1)
    k += sum(1 for a in range(1, p + 1) if gcd(a, p + q - a) == 1)
    return k
